`renderer.destroy()` is only called at the end of the test body; if an assertion throws earlier, the renderer may not be torn down, which can leak resources and make the test suite flaky/hang. Wrap the render/assertions in a try/finally (or use an `afterEach`) to guarantee `renderer.destroy()` runs even on failure.
```suggestion
    try {
      renderer.root.add(
        new TextRenderable(renderer, {
          width: "100%",
          content: new StyledText(chunks),
        }),
      )

      await renderOnce()

      const lines = captureCharFrame()
        .split("\n")
        .map((line) => line.trimEnd())
        .filter(Boolean)

      expect(lines.length).toBeGreaterThan(1)
      expect(lines.join("")).toBe(url)

      const attrs = renderer.currentRenderBuffer.buffers.attributes
      const all = lines.map((line, row) => ids(attrs, renderer.currentRenderBuffer.width, row, line.length))

      expect(all[0]!.size).toBe(1)
      expect(all[1]!.size).toBe(1)
      expect([...all[0]!][0]).toBeGreaterThan(0)

      for (const row of all) {
        expect(row.size).toBe(1)
        expect(row).toEqual(all[0])
      }
    } finally {
      renderer.destroy()
    }
